const {chromium}=require('playwright'),fs=require('fs'),path=require('path');
(async()=>{const b=await chromium.launch({headless:true});const p=await b.newPage({viewport:{width:320,height:950}});const records=[];for(const variant of ['baseline','short-labels-only','zero-padding-only','Arial-only']){await p.goto(process.env.PREVIEW_ROOT+'/leetcode/630/');await p.locator('[data-lang=en]').click();for(const index of [0,3,4]){await p.selectOption('#preset',String(index));const data=await p.locator('#preset').evaluate((el,{variant,index})=>{if(variant==='short-labels-only')el.selectedOptions[0].textContent=({0:'Replacement: 2 courses',3:'All impossible: 0 courses',4:'Tied values: 3 courses'})[index];if(variant==='zero-padding-only')el.style.paddingInline='0px';if(variant==='Arial-only')el.style.fontFamily='Arial';const s=getComputedStyle(el),ctx=document.createElement('canvas').getContext('2d');ctx.font=s.font;const label=el.selectedOptions[0].textContent;const available=el.clientWidth-parseFloat(s.paddingLeft)-parseFloat(s.paddingRight)-16;const measured=ctx.measureText(label).width;return {label,font:s.font,available,measured,fits:measured<=available};},{variant,index});records.push({variant,index,...data});}}fs.mkdirSync(process.env.OUTPUT_DIR,{recursive:true});fs.writeFileSync(path.join(process.env.OUTPUT_DIR,'hypotheses.json'),JSON.stringify({platform:process.platform,browser:b.version(),viewportWidth:320,records},null,2)+'\n');console.log(JSON.stringify(records));await b.close();})().catch(e=>{console.error(e);process.exitCode=1});
